mapper.select:
SELECT symbol, candle_date, close, adjclose, currency, synthetic
FROM price_candle_daily
WHERE symbol = #{symbol}

  AND candle_date >= #{from}


  AND candle_date <= #{to}

ORDER BY candle_date ASC

SELECT nav_date, cash, holdings_value, total_value, cost_basis, unrealised_pnl, realised_pnl_cumulative,
       net_flow, day_pnl, units, nav, estimated
FROM portfolio_nav_daily
WHERE account_id = #{accountId}

  AND nav_date >= #{from}


  AND nav_date <= #{to}

ORDER BY nav_date ASC
